    const n = big ? 100000 : r.int(2, 10);
    const pool = big ? ["a", "b", "c", "d", "e", "f", "g", "h"] : ["a", "b", "c"];
    const words = Array.from({ length: n }, () => r.pick(pool));
    const i = r.int(0, n - 1);
    let j = r.int(0, n - 2);
    if (j >= i) j++;
    words[i] = "a";
    words[j] = "b";
    return r.bool() ? [words, "a", "b"] : [words, "b", "a"];
  }

