function nearestWordGap(words: string[], first: string, second: string): number {
  const a: number[] = [], b: number[] = [];
  words.forEach((w, i) => { if (w === first) a.push(i); else if (w === second) b.push(i); });
  let best = Infinity;
  for (const i of a) for (const j of b) best = Math.min(best, Math.abs(i - j));
  return best;
}

