function nearestWordGap(words: string[], first: string, second: string): number {
  let lastFirst = -1, lastSecond = -1, best = Infinity;
  for (let i = 0; i < words.length; i++) {
    if (words[i] === first) lastFirst = i;
    else if (words[i] === second) lastSecond = i;
    else continue;
    if (lastFirst !== -1 && lastSecond !== -1) best = Math.min(best, Math.abs(lastFirst - lastSecond));
  }
  return best;
}

